-- ==========================================================================
-- PHARMALINK REAL EGYPTIAN TEST DATA SEED SCRIPT  (Full Volume)
-- Tables: AspNetUsers, AspNetUserRoles, Pharmacies, PharmacyBranches,
--   PharmacyBranchSchedules, Addresses, PharmacistAssignments,
--   PharmacyInventories, Carts, CartItems, Orders, OrderItems,
--   OrderFulfillmentLegs, OrderFulfillmentLegStatusAudits,
--   PrescriptionReviews, PrescriptionReviewMedicines,
--   MedicalInquiries, PhoneVerificationOtps, RefreshTokens
-- DOES NOT TOUCH: AspNetRoles, Drugs
-- ==========================================================================

BEGIN TRANSACTION;
BEGIN TRY

    -- ── 0. Resolve role GUIDs from AspNetRoles ─────────────────────────────
    DECLARE @PatientRoleId UNIQUEIDENTIFIER;
    SELECT TOP 1 @PatientRoleId = [Id] FROM [AspNetRoles] WHERE [Name] = 'Patient';
    DECLARE @PharmacistRoleId UNIQUEIDENTIFIER;
    SELECT TOP 1 @PharmacistRoleId = [Id] FROM [AspNetRoles] WHERE [Name] = 'Pharmacist';
    DECLARE @PharmacyAdminRoleId UNIQUEIDENTIFIER;
    SELECT TOP 1 @PharmacyAdminRoleId = [Id] FROM [AspNetRoles] WHERE [Name] = 'PharmacyAdmin';
    DECLARE @AdminRoleId UNIQUEIDENTIFIER;
    SELECT TOP 1 @AdminRoleId = [Id] FROM [AspNetRoles] WHERE [Name] = 'Admin';
    DECLARE @ReviewTeamRoleId UNIQUEIDENTIFIER;
    SELECT TOP 1 @ReviewTeamRoleId = [Id] FROM [AspNetRoles] WHERE [Name] = 'PrescriptionReviewTeam';

    -- ── 1. 30 Pharmacies ─────────────────────────────────────────────────

    -- ── 2. 25 Users (5 per role) ────────────────────────────────────────

    -- ── 3. AspNetUserRoles (25 assignments) ────────────────────────────

    -- ── 4. 90 PharmacyBranches (3 per pharmacy) ─────────────────────────

    -- ── 5. 630 PharmacyBranchSchedules (7 days × 90 branches) ───────────

    -- ── 6. 10 Patient Addresses (2 per patient) ──────────────────────────

    -- ── 7. PharmacistAssignments (active + historical) ──────────────────

    -- ── 8. PharmacyInventories — seed all branches with ALL drugs ────────
    -- (uses CROSS JOIN so every branch × every drug = full inventory)
    IF OBJECT_ID('tempdb..#TempDrugs') IS NOT NULL DROP TABLE #TempDrugs;
    SELECT [DrugId], ROW_NUMBER() OVER (ORDER BY [DrugId]) AS RowNum
    INTO   #TempDrugs FROM [Drugs];

    DECLARE @TotalDrugs INT;
    SELECT @TotalDrugs = COUNT(*) FROM #TempDrugs;

    -- Declare drug variables for later use in Orders/CartItems
    DECLARE @Drug1 UNIQUEIDENTIFIER = NULL;
    DECLARE @Drug2 UNIQUEIDENTIFIER = NULL;
    DECLARE @Drug3 UNIQUEIDENTIFIER = NULL;
    DECLARE @Drug4 UNIQUEIDENTIFIER = NULL;
    DECLARE @Drug5 UNIQUEIDENTIFIER = NULL;
    DECLARE @Drug6 UNIQUEIDENTIFIER = NULL;
    DECLARE @Drug7 UNIQUEIDENTIFIER = NULL;
    DECLARE @Drug8 UNIQUEIDENTIFIER = NULL;
    DECLARE @Drug9 UNIQUEIDENTIFIER = NULL;
    DECLARE @Drug10 UNIQUEIDENTIFIER = NULL;
    IF @TotalDrugs >= 1  SELECT @Drug1  = DrugId FROM #TempDrugs WHERE RowNum = 1;
    IF @TotalDrugs >= 2  SELECT @Drug2  = DrugId FROM #TempDrugs WHERE RowNum = 2;
    IF @TotalDrugs >= 3  SELECT @Drug3  = DrugId FROM #TempDrugs WHERE RowNum = 3;
    IF @TotalDrugs >= 4  SELECT @Drug4  = DrugId FROM #TempDrugs WHERE RowNum = 4;
    IF @TotalDrugs >= 5  SELECT @Drug5  = DrugId FROM #TempDrugs WHERE RowNum = 5;
    IF @TotalDrugs >= 6  SELECT @Drug6  = DrugId FROM #TempDrugs WHERE RowNum = 6;
    IF @TotalDrugs >= 7  SELECT @Drug7  = DrugId FROM #TempDrugs WHERE RowNum = 7;
    IF @TotalDrugs >= 8  SELECT @Drug8  = DrugId FROM #TempDrugs WHERE RowNum = 8;
    IF @TotalDrugs >= 9  SELECT @Drug9  = DrugId FROM #TempDrugs WHERE RowNum = 9;
    IF @TotalDrugs >= 10 SELECT @Drug10 = DrugId FROM #TempDrugs WHERE RowNum = 10;

    IF @TotalDrugs > 0
    BEGIN
        -- Each branch gets ALL drugs in the catalog (full CROSS JOIN)
        -- StockStatus variety: 0-9 → OutOfStock(1), 10-49 → LowStock(2), 50+ → Available(3)
             [UnitPrice],[ExpiryDate],[LastSyncedAt])
        SELECT
            NEWID(),
            b.[BranchId],
            d.[DrugId],
            -- Varied stock: 0,5,8 → out; 10-40 → low; 50-300 → available
            CASE (ABS(CHECKSUM(NEWID())) % 10)
                WHEN 0 THEN 0
                WHEN 1 THEN 5
                WHEN 2 THEN 8
                WHEN 3 THEN 15
                WHEN 4 THEN 25
                WHEN 5 THEN 40
                WHEN 6 THEN 75
                WHEN 7 THEN 120
                WHEN 8 THEN 200
                ELSE       300
            END AS StockQuantity,
            ABS(CHECKSUM(NEWID())) % 8  AS ReservedQuantity,
            CAST(10.00 + (ABS(CHECKSUM(NEWID())) % 490) AS DECIMAL(18,2)) AS UnitPrice,
            CAST(DATEADD(day, 60 + (ABS(CHECKSUM(NEWID())) % 700), CAST(GETDATE() AS DATE)) AS DATE) AS ExpiryDate,
            GETUTCDATE() AS LastSyncedAt
        FROM [PharmacyBranches] b
        CROSS JOIN #TempDrugs d;
    END;

    -- ── 9. Carts (one per patient) and CartItems ─────────────────────────

    IF @TotalDrugs >= 5
    BEGIN
    END;

    -- ── 10. 25 Orders with varied statuses ─────────────────────────────

    -- ── 11. OrderItems (~75 items across 25 orders) ────────────────────
    IF @TotalDrugs >= 5
    BEGIN
    END;

