    INSERT INTO [MedicalInquiries] ([MedicalInquiryId], [PatientUserId], [Question], [Answer], [Status], [AnsweredByUserId], [CreatedAt], [AnsweredAt])
    VALUES
    ('M0000000-0000-0000-0000-000000000001','11111111-0000-0000-0000-000000000001',N'Can I take Panadol Extra during pregnancy?',N'Panadol Extra contains caffeine. Consult your physician before taking caffeine-containing analgesics during pregnancy.',N'Answered','55555555-0000-0000-0000-000000000001',DATEADD(hour,-48,GETUTCDATE()),DATEADD(hour,-24,GETUTCDATE())),
    ('M0000000-0000-0000-0000-000000000002','11111111-0000-0000-0000-000000000002',N'What is the proper dosage timing for Augmentin 1g?',N'Augmentin 1g should be taken every 12 hours with food for 7-10 days as prescribed by your doctor.',N'Answered','55555555-0000-0000-0000-000000000002',DATEADD(hour,-36,GETUTCDATE()),DATEADD(hour,-12,GETUTCDATE())),
    ('M0000000-0000-0000-0000-000000000003','11111111-0000-0000-0000-000000000003',N'Can Cataflam 50mg be taken with blood pressure medication?',N'NSAIDs like Diclofenac (Cataflam) may interact with antihypertensives. Please consult your cardiologist before combining.',N'Answered','55555555-0000-0000-0000-000000000003',DATEADD(hour,-72,GETUTCDATE()),DATEADD(hour,-48,GETUTCDATE())),
    ('M0000000-0000-0000-0000-000000000004','11111111-0000-0000-0000-000000000004',N'Is Glucophage 500mg safe for elderly patients?',N'Metformin (Glucophage) is generally safe for elderly patients with normal kidney function. Regular monitoring of renal function is recommended.',N'Answered','55555555-0000-0000-0000-000000000001',DATEADD(hour,-60,GETUTCDATE()),DATEADD(hour,-30,GETUTCDATE())),
    ('M0000000-0000-0000-0000-000000000005','11111111-0000-0000-0000-000000000005',N'What are the side effects of Zithromax 500mg?',N'Azithromycin may cause nausea, diarrhea, and abdominal pain. Rare cardiac effects have been reported; inform your doctor of any pre-existing heart conditions.',N'Answered','55555555-0000-0000-0000-000000000004',DATEADD(hour,-24,GETUTCDATE()),DATEADD(hour,-6,GETUTCDATE())),
    ('M0000000-0000-0000-0000-000000000006','11111111-0000-0000-0000-000000000001',N'Can I take Omeprazole and Aspirin together?',NULL,N'Pending',NULL,DATEADD(hour,-3,GETUTCDATE()),NULL),
    ('M0000000-0000-0000-0000-000000000007','11111111-0000-0000-0000-000000000002',N'Is Nexium 40mg suitable for chronic GERD treatment?',N'Esomeprazole (Nexium) is appropriate for long-term GERD management under physician supervision. Periodic reassessment is recommended.',N'Answered','55555555-0000-0000-0000-000000000002',DATEADD(hour,-10,GETUTCDATE()),DATEADD(hour,-2,GETUTCDATE())),
    ('M0000000-0000-0000-0000-000000000008','11111111-0000-0000-0000-000000000003',N'What is the difference between Concor 5 and Concor 10?',NULL,N'Pending',NULL,DATEADD(hour,-1,GETUTCDATE()),NULL),
    ('M0000000-0000-0000-0000-000000000009','11111111-0000-0000-0000-000000000004',N'Can children under 12 take Brufen 400mg?',N'Ibuprofen for children should be dosed by weight. Brufen 400mg is generally intended for adults and older children. Consult a pediatrician for children under 12.',N'Answered','55555555-0000-0000-0000-000000000003',DATEADD(hour,-15,GETUTCDATE()),DATEADD(hour,-5,GETUTCDATE())),
    ('M0000000-0000-0000-0000-000000000010','11111111-0000-0000-0000-000000000005',N'How long can I store insulin in the fridge?',N'Unopened insulin vials can be stored in the refrigerator until the expiry date. Once opened, most insulin can be stored at room temperature for up to 28-30 days.',N'Answered','55555555-0000-0000-0000-000000000005',DATEADD(hour,-20,GETUTCDATE()),DATEADD(hour,-10,GETUTCDATE())),
    ('M0000000-0000-0000-0000-000000000011','11111111-0000-0000-0000-000000000001',N'Can I stop taking Atorvastatin 40mg suddenly?',NULL,N'Pending',NULL,DATEADD(hour,-2,GETUTCDATE()),NULL),
    ('M0000000-0000-0000-0000-000000000012','11111111-0000-0000-0000-000000000002',N'What is the half-life of Xanax 0.5mg?',N'Alprazolam (Xanax) has a half-life of approximately 11-15 hours. It should only be used as prescribed due to dependence risk.',N'Answered','55555555-0000-0000-0000-000000000001',DATEADD(hour,-7,GETUTCDATE()),DATEADD(hour,-1,GETUTCDATE())),
    ('M0000000-0000-0000-0000-000000000013','11111111-0000-0000-0000-000000000003',N'Does Amoxicillin treat viral infections?',N'No, Amoxicillin is an antibiotic effective only against bacterial infections. It has no effect on viral infections such as the common cold or flu.',N'Answered','55555555-0000-0000-0000-000000000002',DATEADD(hour,-14,GETUTCDATE()),DATEADD(hour,-3,GETUTCDATE())),
    ('M0000000-0000-0000-0000-000000000014','11111111-0000-0000-0000-000000000004',N'Is it safe to take Voltaren gel and oral Diclofenac together?',N'Combining topical and oral Diclofenac increases systemic exposure and the risk of side effects. Consult your physician before combining both forms.',N'Answered','55555555-0000-0000-0000-000000000004',DATEADD(hour,-9,GETUTCDATE()),DATEADD(hour,-1,GETUTCDATE())),
    ('M0000000-0000-0000-0000-000000000015','11111111-0000-0000-0000-000000000005',N'Can I drink alcohol while taking Metronidazole (Flagyl)?',N'Alcohol must be strictly avoided during Metronidazole treatment and for at least 48 hours after completing the course, due to a severe disulfiram-like reaction risk.',N'Answered','55555555-0000-0000-0000-000000000005',DATEADD(hour,-5,GETUTCDATE()),DATEADD(hour,0,GETUTCDATE())),
    ('M0000000-0000-0000-0000-000000000016','11111111-0000-0000-0000-000000000001',N'What is the correct storage temperature for Amoxil syrup?',NULL,N'Pending',NULL,DATEADD(hour,-1,GETUTCDATE()),NULL),
    ('M0000000-0000-0000-0000-000000000017','11111111-0000-0000-0000-000000000002',N'Is it safe to take Panadol Night during daytime?',N'Panadol Night contains diphenhydramine, a sedating antihistamine. It is not recommended for daytime use due to significant drowsiness and impaired alertness.',N'Answered','55555555-0000-0000-0000-000000000003',DATEADD(hour,-6,GETUTCDATE()),DATEADD(hour,-1,GETUTCDATE())),
    ('M0000000-0000-0000-0000-000000000018','11111111-0000-0000-0000-000000000003',N'Can I use Nasonex spray during pregnancy?',NULL,N'Pending',NULL,GETUTCDATE(),NULL),
    ('M0000000-0000-0000-0000-000000000019','11111111-0000-0000-0000-000000000004',N'How do I know if my blood pressure medication is working?',N'Monitor your blood pressure regularly using a home monitor. Target values are generally below 130/80 mmHg. Keep a log and share it with your physician at follow-up visits.',N'Answered','55555555-0000-0000-0000-000000000001',DATEADD(hour,-11,GETUTCDATE()),DATEADD(hour,-2,GETUTCDATE())),
    ('M0000000-0000-0000-0000-000000000020','11111111-0000-0000-0000-000000000005',N'What is the maximum daily dose of Vitamin D3?',N'For most adults, the safe upper intake level is 4000 IU per day. Therapeutic doses under medical supervision may be higher for documented deficiency. Avoid self-prescribing high doses.',N'Answered','55555555-0000-0000-0000-000000000005',DATEADD(hour,-4,GETUTCDATE()),DATEADD(hour,0,GETUTCDATE()));
